// relayTestBase is the deterministic clock every relay test reads: fixed so
// the RFC3339Nano TEXT stamps round-trip exactly.
var relayTestBase = time.Date(2026, 10, 27, 12, 0, 0, 123456789, time.UTC)

// relayTestLease is the test lease TTL handed out by every claim.
const relayTestLease = 2 * time.Minute

// seedRelayJob inserts one enrich-purpose job for (rowID, pluginID) with a
// minimal single-spec plan and returns its minted id.
func seedRelayJob(t *testing.T, s *Store, rowID, pluginID string) int64 {
	t.Helper()
	id, err := s.CreateRelayJob(context.Background(), RelayJob{
		Purpose:   "enrich",
		RowID:     rowID,
		PluginID:  pluginID,
		Plan:      []PlanSpec{{Method: "GET", URL: "https://upstream.example/" + rowID, TimeoutSeconds: 10}},
		CreatedAt: relayTestBase,
	})
	if err != nil {
		t.Fatalf("CreateRelayJob %s/%s: %v", rowID, pluginID, err)
	}
	return id
}

// TestRelayJobCreate_ClaimRoundTrip covers CreateRelayJob + ClaimOldestRelayJob
// (B2 round-trip shape): a claim hands back the full job verbatim — plan specs
// deep-equal through the JSON blob column, claim stamps exactly as handed out,
// defaults (state/consumed/result) intact — a live lease is not re-claimable,
// claims come oldest-id first, and the search purpose (no row, no library)
// round-trips the same way.
func TestRelayJobCreate_ClaimRoundTrip(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	t.Run("enrich_roundtrip", func(t *testing.T) {
		plan := []PlanSpec{
			{
				Method:         "GET",
				URL:            "https://api.example/tv/1399?api_key=k",
				Headers:        map[string]string{"Authorization": "Bearer k", "Accept": "application/json"},
				TimeoutSeconds: 15,
				MinIntervalMS:  250,
			},
			{
				Method:         "POST",
				URL:            "https://api.example/image",
				Body:           []byte{0x00, 0xff, 0x10, 0x7f},
				BinarySafe:     true,
				TimeoutSeconds: 5,
			},
		}
		id, err := s.CreateRelayJob(ctx, RelayJob{
			Purpose: "enrich", RowID: "itm_1", LibraryID: 7, PluginID: "tmdb",
			Plan: plan, CreatedAt: relayTestBase,
		})
		if err != nil {
			t.Fatalf("CreateRelayJob: %v", err)
		}
		if id <= 0 {
			t.Fatalf("CreateRelayJob id = %d, want > 0", id)
		}

		job, found, err := s.ClaimOldestRelayJob(ctx, "hash-a", relayTestBase, relayTestBase.Add(relayTestLease))
		if err != nil {
			t.Fatalf("ClaimOldestRelayJob: %v", err)
		}
		if !found {
			t.Fatalf("ClaimOldestRelayJob = not found, want the seeded job")
		}
		if job.ID != id || job.Purpose != "enrich" || job.RowID != "itm_1" ||
			job.LibraryID != 7 || job.PluginID != "tmdb" {
			t.Fatalf("claimed job = %+v, want id=%d enrich/itm_1/7/tmdb", job, id)
		}
		if !reflect.DeepEqual(job.Plan, plan) {
			t.Fatalf("plan round-trip mismatch:\n got:  %+v\n want: %+v", job.Plan, plan)
		}
		if job.State != "claimed" || job.ClaimPrincipalHash != "hash-a" {
			t.Fatalf("state/hash = %s/%s, want claimed/hash-a", job.State, job.ClaimPrincipalHash)
		}
		if !job.ClaimedAt.Equal(relayTestBase) || !job.LeaseUntil.Equal(relayTestBase.Add(relayTestLease)) {
			t.Fatalf("claim stamps broken: claimed %v (want %v), lease %v (want %v)",
				job.ClaimedAt, relayTestBase, job.LeaseUntil, relayTestBase.Add(relayTestLease))
		}
		if !job.CreatedAt.Equal(relayTestBase) {
			t.Fatalf("created_at = %v, want %v", job.CreatedAt, relayTestBase)
		}
		if job.Consumed || !job.CompletedAt.IsZero() || job.ResultBytes != 0 || !reflect.DeepEqual(job.Result, RelayResult{}) {
			t.Fatalf("fresh claim defaults broken: consumed=%v completed=%v bytes=%d result=%+v",
				job.Consumed, job.CompletedAt, job.ResultBytes, job.Result)
		}

		// A still-live lease is NOT re-claimable: a second principal finds nothing.
		if _, found, err := s.ClaimOldestRelayJob(ctx, "hash-b",
			relayTestBase.Add(time.Minute), relayTestBase.Add(time.Minute).Add(relayTestLease)); err != nil || found {
			t.Fatalf("claim on live lease = found=%v err=%v, want false/nil", found, err)
		}
	})

	t.Run("oldest_first", func(t *testing.T) {
		fresh := openStore(t)
		first := seedRelayJob(t, fresh, "itm_old", "tmdb")
		seedRelayJob(t, fresh, "itm_new", "tmdb")
		job, found, err := fresh.ClaimOldestRelayJob(ctx, "hash-a", relayTestBase, relayTestBase.Add(relayTestLease))
		if err != nil || !found {
			t.Fatalf("claim oldest = found=%v err=%v, want the first-seeded job", found, err)
		}
		if job.ID != first {
			t.Fatalf("claim returned id %d, want oldest %d", job.ID, first)
		}
	})

	t.Run("search_purpose_roundtrip", func(t *testing.T) {
		plan := []PlanSpec{{Method: "GET", URL: "https://api.example/search?q=one+piece", TimeoutSeconds: 20}}
		id, err := s.CreateRelayJob(ctx, RelayJob{
			Purpose: "search", PluginID: "shiki", Plan: plan, CreatedAt: relayTestBase,
		})
		if err != nil {
			t.Fatalf("CreateRelayJob search: %v", err)
		}
		job, found, err := s.ClaimOldestRelayJob(ctx, "hash-s",
			relayTestBase.Add(2*time.Minute), relayTestBase.Add(2*time.Minute).Add(relayTestLease))
		if err != nil || !found {
			t.Fatalf("claim search job = found=%v err=%v", found, err)
		}
		if job.ID != id || job.Purpose != "search" || job.RowID != "" || job.LibraryID != 0 || job.PluginID != "shiki" {
			t.Fatalf("search job = %+v, want id=%d search//0/shiki", job, id)
		}
		if !reflect.DeepEqual(job.Plan, plan) {
			t.Fatalf("search plan round-trip mismatch:\n got:  %+v\n want: %+v", job.Plan, plan)
		}
	})
}

// TestRelayJobClaimRace asserts the D3 single-claimant guarantee AS A RACE:
// concurrent ClaimOldestRelayJob calls over one store yield exactly
// min(jobs, claimants) winners, every claimed id distinct — the losers'
// updates touch 0 rows and read as not-found (never spin, never error).
func TestRelayJobClaimRace(t *testing.T) {
	ctx := context.Background()
	cases := []struct {
		name      string
		jobs      int
		claimants int
		wantFound int
	}{
		{"one_job_two_claimants", 1, 2, 1},
		{"three_jobs_five_claimants", 3, 5, 3},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s := openStore(t)
			for i := 0; i < tc.jobs; i++ {
				seedRelayJob(t, s, fmt.Sprintf("itm_race_%d", i), "tmdb")
			}

			type outcome struct {
				jobID int64
				found bool
			}
			results := make(chan outcome, tc.claimants)
			start := make(chan struct{}) // releases all claimants at once
			var wg sync.WaitGroup
			for n := 0; n < tc.claimants; n++ {
				wg.Add(1)
				go func(principal int) {
					defer wg.Done()
					<-start
					job, found, err := s.ClaimOldestRelayJob(ctx,
						fmt.Sprintf("hash-%d", principal),
						relayTestBase, relayTestBase.Add(relayTestLease))
					if err != nil {
						t.Errorf("claimant %d: %v", principal, err)
						return
					}
					results <- outcome{jobID: job.ID, found: found}
				}(n)
			}
			close(start)
			wg.Wait()
			close(results)

			found, seen := 0, map[int64]bool{}
			for r := range results {
				if !r.found {
					continue
				}
				found++
				if seen[r.jobID] {
					t.Fatalf("job %d claimed by two principals — single-claimant broken", r.jobID)
				}
				seen[r.jobID] = true
			}
			if found != tc.wantFound {
				t.Fatalf("concurrent claims = %d found, want exactly %d", found, tc.wantFound)
			}
		})
	}
}

// TestRelayJobLeaseReclaim asserts the LAZY lease semantics (the pairing
// lazy-expiry precedent, decided inside the claim predicate): a live lease is
// not re-claimable (strictly — even exactly AT lease_until), one tick past it
// is, and the re-claim hands the SAME job to the new principal with fresh
// stamps.
func TestRelayJobLeaseReclaim(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	id := seedRelayJob(t, s, "itm_re", "tmdb")

	if _, found, err := s.ClaimOldestRelayJob(ctx, "hash-a", relayTestBase, relayTestBase.Add(relayTestLease)); err != nil || !found {
		t.Fatalf("first claim = found=%v err=%v", found, err)
	}

	steps := []struct {
		name string
		now  time.Time
		want bool
	}{
		{"mid_lease", relayTestBase.Add(time.Minute), false},
		{"exactly_at_lease_until_strict", relayTestBase.Add(relayTestLease), false},
		{"one_tick_past_lease", relayTestBase.Add(relayTestLease).Add(time.Nanosecond), true},
	}
	for _, tc := range steps {
		t.Run(tc.name, func(t *testing.T) {
			job, found, err := s.ClaimOldestRelayJob(ctx, "hash-b", tc.now, tc.now.Add(relayTestLease))
			if err != nil {
				t.Fatalf("claim at %v: %v", tc.now, err)
			}
			if found != tc.want {
				t.Fatalf("claim at %v = found %v, want %v", tc.now, found, tc.want)
			}
			if !found {
				return
			}
			if job.ID != id {
				t.Fatalf("re-claim returned id %d, want the same job %d", job.ID, id)
			}
			if job.ClaimPrincipalHash != "hash-b" || !job.ClaimedAt.Equal(tc.now) || !job.LeaseUntil.Equal(tc.now.Add(relayTestLease)) {
				t.Fatalf("re-claim stamps = %s/%v/%v, want hash-b/%v/%v",
					job.ClaimPrincipalHash, job.ClaimedAt, job.LeaseUntil, tc.now, tc.now.Add(relayTestLease))
			}
		})
	}
}

// TestRelayJobCompleteGuard asserts CompleteRelayJob's guard is the SAME
// principal hash AND a live lease: a wrong principal, an expired lease, or an
// unknown id is a wrapped sql.ErrNoRows that leaves the row untouched, the
// happy path moves claimed→done with the result stored verbatim, and a done
// job never re-enters the claimable set.
func TestRelayJobCompleteGuard(t *testing.T) {
	ctx := context.Background()
	t0 := relayTestBase
	leaseUntil := t0.Add(relayTestLease)
	result := RelayResult{
		HTTPStatus: 200,
		Headers:    map[string]string{"Content-Type": "application/json"},
		Body:       []byte(`{"results":[{"id":1}]}`),
	}

	cases := []struct {
		name         string
		claimHash    string
		completeHash string
		completeNow  time.Time
		wantErr      bool
	}{
		{"wrong_principal", "hash-a", "hash-other", t0.Add(time.Minute), true},
		{"expired_lease", "hash-a", "hash-a", leaseUntil.Add(time.Second), true},
		{"lease_boundary_exclusive", "hash-a", "hash-a", leaseUntil, true},
		{"happy_inside_lease", "hash-a", "hash-a", t0.Add(time.Minute), false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s := openStore(t)
			id := seedRelayJob(t, s, "itm_g", "tmdb")
			if _, found, err := s.ClaimOldestRelayJob(ctx, tc.claimHash, t0, leaseUntil); err != nil || !found {
				t.Fatalf("setup claim = found=%v err=%v", found, err)
			}

			err := s.CompleteRelayJob(ctx, id, tc.completeHash, "done", result, tc.completeNow)
			if tc.wantErr {
				if !errors.Is(err, sql.ErrNoRows) {
					t.Fatalf("complete = %v, want wrapped sql.ErrNoRows", err)
				}
				// The refused complete left the row claimed and untouched: past the
				// lease it is claimable again — by the (different) next principal.
				job, found, err := s.ClaimOldestRelayJob(ctx, "hash-c",
					leaseUntil.Add(time.Minute), leaseUntil.Add(3*time.Minute))
				if err != nil || !found || job.ID != id {
					t.Fatalf("refused complete must leave the job reclaimable: found=%v id=%d err=%v", found, job.ID, err)
				}
				return
			}
			if err != nil {
				t.Fatalf("complete: %v", err)
			}

			// A done job left the claimable set.
			if _, found, _ := s.ClaimOldestRelayJob(ctx, "hash-c",
				leaseUntil.Add(time.Minute), leaseUntil.Add(3*time.Minute)); found {
				t.Fatalf("done job was re-claimable")
			}
			// Reach-in (the DeleteLibrary count idiom): state, result blob,
			// derived result_bytes and completed_at as stored.
			var (
				state       string
				resultBlob  []byte
				resultBytes int
				completedAt sql.NullString
				consumed    int
			)
			if err := s.db.QueryRowContext(ctx,
				"SELECT state, result, result_bytes, completed_at, consumed FROM relay_jobs WHERE id = ?", id,
			).Scan(&state, &resultBlob, &resultBytes, &completedAt, &consumed); err != nil {
				t.Fatalf("select completed row: %v", err)
			}
			if state != "done" {
				t.Fatalf("state = %q, want done", state)
			}
			var got RelayResult
			if err := json.Unmarshal(resultBlob, &got); err != nil {
				t.Fatalf("result blob: %v", err)
			}
			if !reflect.DeepEqual(got, result) {
				t.Fatalf("result round-trip mismatch:\n got:  %+v\n want: %+v", got, result)
			}
			if resultBytes != len(result.Body) {
				t.Fatalf("result_bytes = %d, want %d (derived body length)", resultBytes, len(result.Body))
			}
			completed, err := parseTime(completedAt.String)
			if err != nil || !completed.Equal(tc.completeNow) {
				t.Fatalf("completed_at = %v (%v), want %v", completedAt.String, err, tc.completeNow)
			}
		})
	}

	t.Run("failed_state_roundtrip", func(t *testing.T) {
		s := openStore(t)
		id := seedRelayJob(t, s, "itm_f", "tmdb")
		if _, found, err := s.ClaimOldestRelayJob(ctx, "hash-a", t0, leaseUntil); err != nil || !found {
			t.Fatalf("setup claim = found=%v err=%v", found, err)
		}
		failed := RelayResult{HTTPStatus: 502, Error: "dial tcp: connection refused"}
		if err := s.CompleteRelayJob(ctx, id, "hash-a", "failed", failed, t0.Add(time.Minute)); err != nil {
			t.Fatalf("complete failed: %v", err)
		}
		var (
			state      string
			resultBlob []byte
		)
		if err := s.db.QueryRowContext(ctx,
			"SELECT state, result FROM relay_jobs WHERE id = ?", id).Scan(&state, &resultBlob); err != nil {
			t.Fatalf("select failed row: %v", err)
		}
		if state != "failed" {
			t.Fatalf("state = %q, want failed", state)
		}
		var got RelayResult
		if err := json.Unmarshal(resultBlob, &got); err != nil {
			t.Fatalf("result blob: %v", err)
		}
		if !reflect.DeepEqual(got, failed) {
			t.Fatalf("failed result round-trip mismatch:\n got:  %+v\n want: %+v", got, failed)
		}
		// The failed round is exactly what CountRelayRounds counts (D5 input).
		n, err := s.CountRelayRounds(ctx, "itm_f", "tmdb")
		if err != nil || n != 1 {
			t.Fatalf("CountRelayRounds = %d, %v; want 1, nil", n, err)
		}
	})

	t.Run("unknown_id", func(t *testing.T) {
		s := openStore(t)
		if err := s.CompleteRelayJob(ctx, 424242, "hash-a", "done", result, t0.Add(time.Minute)); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("complete unknown = %v, want wrapped sql.ErrNoRows", err)
		}
	})
}

// TestRelayJobMarkConsumed covers the consult-side consume flag: an unknown id
// is a wrapped sql.ErrNoRows, a known id flips consumed to 1, and re-marking
// is a harmless rewrite (never an error).
func TestRelayJobMarkConsumed(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	if err := s.MarkRelayConsumed(ctx, 999); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("mark unknown = %v, want wrapped sql.ErrNoRows", err)
	}

	id := seedRelayJob(t, s, "itm_c", "tmdb")
	if err := s.MarkRelayConsumed(ctx, id); err != nil {
		t.Fatalf("MarkRelayConsumed: %v", err)
	}
	var consumed int
	if err := s.db.QueryRowContext(ctx,
		"SELECT consumed FROM relay_jobs WHERE id = ?", id).Scan(&consumed); err != nil {
		t.Fatalf("select consumed: %v", err)
	}
	if consumed != 1 {
		t.Fatalf("consumed = %d, want 1", consumed)
	}
	if err := s.MarkRelayConsumed(ctx, id); err != nil {
		t.Fatalf("MarkRelayConsumed re-mark = %v, want nil (idempotent rewrite)", err)
	}
}

// TestRelayJobCountRounds covers the give-up input (D5): the count is over one
// (row_id, plugin_id) pair's failed jobs only — done rows never count, another
// plugin's or another row's failures never count, and an empty ledger is 0.
func TestRelayJobCountRounds(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	t0 := relayTestBase

	failRound := func(rowID, pluginID string) {
		t.Helper()
		id := seedRelayJob(t, s, rowID, pluginID)
		if _, found, err := s.ClaimOldestRelayJob(ctx, "hash-a", t0, t0.Add(relayTestLease)); err != nil || !found {
			t.Fatalf("setup claim %s/%s = found=%v err=%v", rowID, pluginID, found, err)
		}
		if err := s.CompleteRelayJob(ctx, id, "hash-a", "failed",
			RelayResult{HTTPStatus: 502, Error: "boom"}, t0.Add(time.Minute)); err != nil {
			t.Fatalf("complete failed %s/%s: %v", rowID, pluginID, err)
		}
	}

	n, err := s.CountRelayRounds(ctx, "itm_k", "tmdb")
	if err != nil || n != 0 {
		t.Fatalf("empty ledger count = %d, %v; want 0, nil", n, err)
	}

	failRound("itm_k", "tmdb")
	failRound("itm_k", "tmdb")     // the pair's two failed rounds...
	failRound("itm_k", "shiki")    // ...another plugin's failure never counts
	failRound("itm_other", "tmdb") // ...another row's failure never counts
	doneID := seedRelayJob(t, s, "itm_k", "tmdb")
	if _, found, err := s.ClaimOldestRelayJob(ctx, "hash-a", t0.Add(relayTestLease), t0.Add(3*relayTestLease)); err != nil || !found {
		t.Fatalf("setup claim done = found=%v err=%v", found, err)
	}
	if err := s.CompleteRelayJob(ctx, doneID, "hash-a", "done",
		RelayResult{HTTPStatus: 200, Body: []byte(`{}`)}, t0.Add(2*relayTestLease)); err != nil {
		t.Fatalf("complete done: %v", err)
	}

	n, err = s.CountRelayRounds(ctx, "itm_k", "tmdb")
	if err != nil || n != 2 {
		t.Fatalf("CountRelayRounds(itm_k, tmdb) = %d, %v; want 2 failed rounds only", n, err)
	}
}
